import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const toolsDirectory = path.dirname(fileURLToPath(import.meta.url));
const realmDirectory = path.resolve(toolsDirectory, "..");
const sourceDirectory = path.join(realmDirectory, "src");
const htmlPath = path.join(realmDirectory, "clawdvert_channel.html");
const startMarker = "  // AUTO_ANSWER_BUNDLE_START";
const endMarker = "  // AUTO_ANSWER_BUNDLE_END";
const checkOnly = process.argv.slice(2).includes("--check");
if (process.argv.slice(2).some(argument => argument !== "--check")) {
  throw new Error("Usage: node realm/tools/build-auto-answer-bundle.mjs [--check]");
}

function moduleSource(name) {
  return fs.readFileSync(path.join(sourceDirectory, name), "utf8")
    .replace(/^import\s*\{[\s\S]*?\}\s*from\s*["'][^"']+["'];\s*/gm, "")
    .replace(/^export\s+/gm, "")
    .trim();
}

function indent(source, spaces = 4) {
  const prefix = " ".repeat(spaces);
  return source.split("\n").map(line => line ? prefix + line : "").join("\n");
}

const codec = moduleSource("rendezvous-v2-codec.js");
const sdp = moduleSource("rendezvous-v2-sdp.js");
const autoReturn = moduleSource("auto-answer-return.js");
const slotTransport = moduleSource("rendezvous-v2-transport.js");
const turnExchange = moduleSource("rendezvous-v2-turn-exchange.js");

const bundle = `${startMarker}
  // Generated by realm/tools/build-auto-answer-bundle.mjs. Do not edit here.
  const AutoAnswerCodec = (() => {
${indent(codec)}
    return Object.freeze({
      RENDEZVOUS_V2,
      encodeAndSignRendezvousV2Bytes,
      verifyAndDecodeRendezvousV2Bytes,
      formatSdpCandidate,
      normalizeRendezvousCandidate,
      parseSdpCandidate
    });
  })();
  const AutoAnswerSdp = (({
    formatSdpCandidate, normalizeRendezvousCandidate, parseSdpCandidate
  }) => {
${indent(sdp)}
    return Object.freeze({
      addRendezvousCandidates,
      buildRendezvousDataChannelSdp,
      candidateToIceCandidateInit,
      extractRendezvousIce,
      selectRendezvousCandidates
    });
  })(AutoAnswerCodec);
  const AutoAnswerReturn = (({
    RENDEZVOUS_V2, encodeAndSignRendezvousV2Bytes, verifyAndDecodeRendezvousV2Bytes
  }, {
    buildRendezvousDataChannelSdp, extractRendezvousIce, selectRendezvousCandidates
  }) => {
${indent(autoReturn)}
    return Object.freeze({
      AUTO_ANSWER_RETURN,
      AutoAnswerReturnError,
      createAutoAnswerInviteDescriptor,
      validateAutoAnswerInviteDescriptor,
      deriveAutoAnswerReturnKeys,
      createAutoAnswerSlot,
      verifyAutoAnswerAnswerSlot
    });
  })(AutoAnswerCodec, AutoAnswerSdp);
  const AutoAnswerTransport = (() => {
${indent(slotTransport)}
    return Object.freeze({
      RendezvousV2SlotTransport,
      RendezvousV2TransportError,
      RENDEZVOUS_V2_WILDCARD_DEVICE
    });
  })();
  const AutoAnswerTurnExchange = (() => {
${indent(turnExchange)}
    return Object.freeze({ createRendezvousV2TurnExchange });
  })();
${endMarker}`;

const html = fs.readFileSync(htmlPath, "utf8");
const start = html.indexOf(startMarker);
const end = html.indexOf(endMarker);
if (start < 0 || end < start) throw new Error("Auto-answer bundle markers are missing from the HTML.");
const updated = html.slice(0, start) + bundle + html.slice(end + endMarker.length);
if (checkOnly) {
  if (updated !== html) {
    console.error("Auto-answer bundle is stale. Run realm/tools/build-auto-answer-bundle.mjs.");
    process.exitCode = 1;
  } else {
    console.log("Auto-answer bundle is current.");
  }
} else {
  fs.writeFileSync(htmlPath, updated);
}
